// СГЕНЕРИРОВАНО tools/airdef-headless/sync-shared.js из games/airdef — не править здесь
// Арсенал «Воздушного превосходства»: ударное оружие самолёта (AG) и зенитные комплексы (SAM).
// Реальные ТТХ — округлённые открытые данные («≈»). Игровые параметры (дальности, урон, кинематика) подогнаны
// под арену ~30 км и прочность объектов игры: это аркада с реальными механиками наведения, а не тренажёр.
//
// AG — поля: era — эпоха (1 — 1960–70-е, 2 — 1980-е, 3 — 1990–2000-е, 4 — сейчас), side — 'east' | 'west';
//   kind: 'bomb' — свободнопадающая (прицел CCIP); 'lgb' — бомба с лазерной полуактивной ГСН (подсвет до попадания);
//         'tvb' — бомба с телевизионной ГСН «выстрелил и забыл» (захват до сброса); 'agm' — ракета (ГСН: seeker);
//         'arm' — противорадиолокационная (наводится на излучение РЛС).
//   seeker (у agm): 'tv' — захват контейнером до пуска, дальше сама; 'laser' — нужна подсветка до попадания.
//   mem (у arm): помнит, где была РЛС, если та выключилась (HARM, Х-58); без памяти (Shrike, Х-28) — промах.
//   Кинематика: kd — сопротивление (×1e-4), g — располагаемая перегрузка рулей, acc/burn — двигатель (у ракет),
//     life — время полёта до самоликвидации; fov — поле зрения ГСН от оси, °; lockR — дальность захвата ГСН, м;
//     rmax — наибольшая дальность пуска (подсказка), м. dmg/blast — урон в центре и радиус поражения.
// SAM — поля: type: 'command' (радиокомандное: ракету ведёт РЛС комплекса), 'sarh' (полуактивное: нужен подсвет цели),
//   'ir' (тепловая ГСН, РЛС не нужна), 'saclos' (команды по линии визирования; оптика — без излучения), 'guns' (зенитная артиллерия);
//   radar: { range — обнаружение цели с ЭПР 5 м², м; acq — время захвата, с; doppler — когерентная РЛС: цель «траверзом»
//     теряется (провал); clutter — ниже этой высоты над землёй РЛС не видит цель на фоне земли; mast — высота антенны; band — для СПО };
//   optical — дальность обнаружения глазом/оптикой (у ИК и оптических); rmin/rmax/hmin/hmax — зона поражения, м;
//   react — время реакции (от захвата до пуска), с; salvo — ракет на цель; ammo — готовых ракет; reload — перезарядка, с;
//   eccm — помехозащищённость 0…1 (против диполей); rwr — значок на экране СПО; hp — прочность машины.

